import {modules,lessons,sources} from './content.js';
import {challenges} from './challenges.js';
import {codingWorkbench} from './coding-workbench.js';
import {writtenQuestions} from './exam-bank.js';
import {writtenCard,difficulty} from './exam-ui.js';
import {createOptionLayouts,optionLetter} from './question-options.js';
import {beginnerGuide,beginnerSequence,hasBeginnerNotes,modulePrimer} from './beginner-reading.js';
import {explanation,workedExample,relatedReasoning,tutorialFor,hasWalkthrough,walkthroughFor,renderWalkthrough} from './lesson-reading.js';

const KEY='embedded-study-v1';
const moduleById=Object.fromEntries(modules.map(m=>[m.id,m]));
const lessonById=Object.fromEntries(lessons.map(l=>[l.id,l]));
const questionById=Object.fromEntries(lessons.flatMap(l=>l.quiz.map(q=>[q.id,{...q,lesson:l}])));
const allQuestions=lessons.flatMap(l=>l.quiz);
const questionCount=allQuestions.length;
const optionLayouts=createOptionLayouts(allQuestions);
const letter=(q,index)=>optionLetter(optionLayouts.get(q.id),index);
const app=document.querySelector('#app');
let state=loadState();
let route='home',routeArg='',searchTerm='',practiceModule='all',practiceLimit=12,showOnlyDue=false,practiceDifficulty='进阶',practiceType='all',codingModule='all',codingDifficulty='all';
let lessonView={},lessonLevel={},lessonCodeChoice={};
let visualStep={},spiMode=0,mobileOpen=false,mock=null,mockTimer=null;

function loadState(){
  try {const saved=JSON.parse(localStorage.getItem(KEY)||'{}');return {completed:saved.completed||{},answers:saved.answers||{},drafts:saved.drafts||{},lastLesson:saved.lastLesson||null};}
  catch{return {completed:{},answers:{},drafts:{},lastLesson:null};}
}
function saveState(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('无法保存到浏览器，请尝试导出学习记录。');return false;}}
const E=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const pct=(a,b)=>b?Math.round(a/b*100):0;
const completedCount=()=>lessons.filter(l=>state.completed[l.id]).length;
const answeredCount=()=>Object.values(state.answers).filter(a=>a.submitted).length;
const wrongCount=()=>Object.values(state.answers).filter(a=>a.needsReview).length;
const dueCount=()=>Object.values(state.answers).filter(a=>a.needsReview&&(!a.due||a.due<=Date.now())).length;
const lessonUrl=id=>`#/lesson/${id}`;
const moduleUrl=id=>`#/module/${id}`;
function setRoute(){
  const h=decodeURIComponent(location.hash.replace(/^#\/?/,''))||'home';
  const parts=h.split('/');route=parts[0]||'home';routeArg=parts[1]||'';
  if(route==='lesson'&&['practice','coding'].includes(parts[2])){lessonView[routeArg]='practice';if(parts[2]==='coding')lessonLevel[routeArg]='coding';}
  if(!['home','module','lesson','practice','review','mock','challenges','challenge','sources','search'].includes(route)) route='home';
  if(route==='lesson'&&lessonById[routeArg]){state.lastLesson=routeArg;saveState();}
  if(route==='practice'&&moduleById[routeArg]){practiceModule=routeArg;practiceLimit=12;}
  mobileOpen=false;render();window.scrollTo(0,0);
}
function toast(message){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.textContent=message;document.body.append(t);setTimeout(()=>t.remove(),3400);}
function currentTitle(){
  if(route==='module')return moduleById[routeArg]?.name||'课程目录';
  if(route==='lesson')return lessonById[routeArg]?.title||'课程';
  return {home:'学习首页',practice:'专题练习',review:'错题复习',mock:'模拟笔试',challenges:'编程题',challenge:'编程题',sources:'资料来源',search:'搜索结果'}[route]||'学习首页';
}
function navItem(url,icon,label,count,active){return `<a class="nav-link ${active?'active':''}" href="${url}"><span class="nav-icon">${icon}</span><span>${E(label)}</span>${count!==undefined?`<span class="nav-count">${count}</span>`:''}</a>`;}
function shell(){
  app.innerHTML=`<div class="shell"><div class="mobile-shade ${mobileOpen?'open':''}" data-action="close-menu"></div><aside class="sidebar ${mobileOpen?'open':''}"><div class="brand"><div class="brand-mark">{}</div><div>嵌入式秋招学习站<small>MCU · FREERTOS · C/C++</small></div></div><div class="side-scroll"><div class="side-label">学习空间</div>${navItem('#/home','⌂','学习首页',undefined,route==='home')}${navItem('#/practice','◫','专题练习',questionCount+writtenQuestions.length+challenges.length,route==='practice')}${navItem('#/challenges','⌨','编程题',challenges.length,route==='challenges'||route==='challenge')}${navItem('#/review','↺','错题复习',wrongCount(),route==='review')}${navItem('#/mock','◷','模拟笔试',undefined,route==='mock')}<div class="side-label">知识模块</div>${modules.map(m=>navItem(moduleUrl(m.id),E(m.icon),m.name,lessons.filter(l=>l.module===m.id).length,route==='module'&&routeArg===m.id||route==='lesson'&&lessonById[routeArg]?.module===m.id)).join('')}<div class="side-label">资料</div>${navItem('#/sources','↗','资料来源',undefined,route==='sources')}</div><div class="side-foot">学习记录仅保存在当前浏览器 · 可导出备份</div></aside><div class="main"><header class="topbar"><button class="mobile-menu" data-action="toggle-menu" aria-label="打开课程菜单">☰</button><span class="top-title">嵌入式秋招学习站</span><span class="top-sep">/</span><span class="top-sub">${E(currentTitle())}</span><div class="search-wrap"><span class="search-icon">⌕</span><input id="site-search" type="search" placeholder="搜索：指针、SPI、互斥锁…" aria-label="搜索课程和题目" value="${E(searchTerm)}"><span class="search-hint">↵</span></div><span class="top-avatar" title="个人学习记录">学</span></header><main class="content" id="page-content"></main></div></div>`;
  renderMain();
}
function render(){shell();}
function renderMain(preserve=false){const container=document.querySelector('#page-content');if(!container)return;const oldY=window.scrollY;
  let html='';switch(route){case 'home':html=homePage();break;case 'module':html=modulePage(routeArg);break;case 'lesson':html=lessonPage(routeArg);break;case 'practice':html=practicePage();break;case 'review':html=reviewPage();break;case 'mock':html=mockPage();break;case 'challenges':html=challengesPage();break;case 'challenge':html=challengePage(routeArg);break;case 'sources':html=sourcesPage();break;case 'search':html=searchPage();break;default:html=homePage();}
  container.innerHTML=html;if(preserve)window.scrollTo(0,oldY);
}
function pageHead(label,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${E(label)}</div><h1>${E(title)}</h1><p>${E(description)}</p></div>${action}</div>`;}
function moduleCard(m){const items=lessons.filter(l=>l.module===m.id),done=items.filter(l=>state.completed[l.id]).length;return `<a class="module-card" style="--mod:${m.color}" href="${moduleUrl(m.id)}"><div class="module-top"><div class="module-symbol">${E(m.icon)}</div><span class="module-arrow">↗</span></div><h3>${E(m.name)}</h3><p>${E(m.description)}</p><div class="progress"><span style="width:${pct(done,items.length)}%"></span></div><div class="progress-note">${done} / ${items.length} 课已完成</div></a>`;}
function courseCard(l,index){const done=state.completed[l.id],codingCount=challenges.filter(c=>c.lesson===l.id||c.relatedLessons?.includes(l.id)).length;return `<a class="course-card" href="${lessonUrl(l.id)}"><span class="course-num">${String(index+1).padStart(2,'0')}</span><div class="course-body"><strong>${E(l.title)}</strong><p>${E(l.summary)}</p>${codingCount?`<span class="course-lab-note">随堂编程 ${codingCount} 题 · 可直接写代码</span>`:''} </div><div class="course-side"><span class="badge ${done?'done':l.level.toLowerCase()}">${done?'已完成':l.level}</span><span class="arrow">›</span></div></a>`;}
function homePage(){
 const next=lessons.find(l=>!state.completed[l.id])||lessons[0],resume=lessonById[state.lastLesson]||next;
 return `<header class="work-home"><div><div class="eyebrow">MCU · C / C++ · FREERTOS</div><h1>嵌入式学习工作台</h1><p>看懂一个知识点，再亲手写出它。基础题、笔试题与编程题按课程整理。</p></div><div class="home-actions"><a class="btn primary" href="${lessonUrl(resume.id)}">继续学习 →</a><a class="btn ghost" href="#/practice">打开题库</a></div></header>
 <div class="home-statline"><span><b>${lessons.length}</b> 节课程</span><span><b>${challenges.length}</b> 道编程与场景题</span><span><b>${completedCount()}</b> 课已完成</span><span><b>${dueCount()}</b> 道错题待复习</span></div>
 <section class="training-routes" aria-label="开始练习"><div class="training-route"><span>01 / C LANGUAGE</span><h2>从指针到内存</h2><p>数组、字符串、结构体与回调；把指针推演写成真正的函数。</p><a class="btn soft" href="#/lesson/c-pointer/coding">进入 C 随堂编程 →</a></div><div class="training-route"><span>02 / C++</span><h2>对象、生命周期与所有权</h2><p>构造析构、深拷贝、移动与 RAII；练习成功和失败的每条路径。</p><a class="btn soft" href="#/lesson/cpp-copy/coding">进入 C++ 随堂编程 →</a></div><div class="training-route"><span>03 / EXAM PRACTICE</span><h2>从会读到会解</h2><p>按模块、难度和题型刷题，先独立作答，再展开详细解析。</p><a class="btn soft" href="#/practice">进入进阶题库 →</a></div></section>
 <details class="foundation-entry"><summary>还不熟悉 sizeof、& 与 *？展开从零开始的学习路线</summary>${beginnerGuide({compact:true})}</details>
 <div class="section-head"><div><h2>知识地图</h2><p>选择模块，按课程学习与练习</p></div><a class="btn link" href="#/review">复习错题 →</a></div><div class="module-grid">${modules.map(moduleCard).join('')}</div>`;
}
function modulePage(id){const m=moduleById[id];if(!m)return notFound();const items=lessons.filter(l=>l.module===id),done=items.filter(l=>state.completed[l.id]).length;return `${pageHead('知识模块',m.name,m.description,`<span class="badge p0">${done} / ${items.length} 课完成</span>`)}<div class="panel" style="padding:18px 21px;margin-bottom:18px"><div class="progress" style="--mod:${m.color};height:7px"><span style="width:${pct(done,items.length)}%"></span></div><p style="font-size:11px;color:#8998ad;margin:8px 0 0">先按入门课程的序号学习，再进入 P0 高频知识；基础练习之后，再做进阶笔试题与手写题。</p></div>${id==='c'?beginnerGuide():modulePrimer(id)}<div class="course-list">${items.map(courseCard).join('')}</div><div class="section-head"><h2>继续练习</h2></div><a href="#/practice/${id}" class="btn ghost">练本模块笔试题　→</a>`;}
function notFound(){return `<div class="empty"><div class="big">◇</div>没有找到这一页。<p><a href="#/home">返回首页</a></p></div>`;}
function lessonPage(id){
 const l=lessonById[id];if(!l)return notFound();
 const m=moduleById[l.module],i=lessons.indexOf(l),prev=lessons[i-1],next=lessons[i+1];
 const relevant=challenges.filter(c=>c.lesson===id||c.relatedLessons?.includes(id));
 const written=writtenQuestions.filter(q=>q.lesson===id),basic=l.quiz.filter(q=>!q.difficulty),advanced=l.quiz.filter(q=>q.difficulty);
 const diagram=hasWalkthrough(l)||l.visual,view=lessonView[id]||'reading';
 const group=lessonLevel[id]||(relevant.length?'coding':advanced.length+written.length?'advanced':'basic');
 const selected=relevant.find(c=>c.id===lessonCodeChoice[id])||(l.beginner?relevant[0]:relevant.find(c=>c.level!=='入门')||relevant[0]);
 const refs=sources.filter(s=>l.module==='c'?s.name.includes('N1570')||s.name.includes('AAPCS'):l.module==='cpp'?s.name.includes('C++'):['stm32','protocol','project'].includes(l.module)?s.name.includes(l.id==='p-spi'?'AN5543':'STM32'):l.module==='rtos'||l.module==='os'?s.name.includes('FreeRTOS'):l.module==='arm'?s.name.includes('AAPCS')||s.name.includes('Cortex'):l.module==='memory'?s.name.includes('AAPCS')||s.name.includes('STM32'):false);
 const total=l.quiz.length+written.length+relevant.length;
 return `<div class="crumb"><a href="#/home">学习工作台</a> / <a href="${moduleUrl(m.id)}">${E(m.name)}</a> / ${E(l.title)}</div>
 <header class="lesson-heading"><div><div class="eyebrow">${E(m.name)} · ${E(l.level)}</div><h1>${E(l.title)}</h1><p>${E(l.summary)}</p></div><a class="btn ghost" href="${moduleUrl(m.id)}">课程目录</a></header>
 <div class="lesson-modes" role="group" aria-label="课程视图"><button data-action="lesson-view" data-id="${id}" data-value="reading" aria-pressed="${view==='reading'}">知识讲解</button><button data-action="lesson-view" data-id="${id}" data-value="practice" aria-pressed="${view==='practice'}">随堂练习 <span>${total}</span></button><div class="lesson-breakdown">基础 ${basic.length} · 进阶 ${advanced.length+written.length} · 编程 ${relevant.length}</div></div>
 <div class="lesson-layout lesson-reading-view" ${view==='reading'?'':'hidden'}><article class="article panel">${beginnerSequence(l)}
 <div class="lesson-entry"><span>读懂原理后，用本课练习检验。</span><button class="btn soft" data-action="lesson-view" data-id="${id}" data-value="practice">开始随堂练习 →</button></div>
 ${explanation(l)}<h2 id="concept">关键结论与适用条件</h2>${hasBeginnerNotes(l)?'<details class="advanced-reasoning"><summary>展开笔试规则与平台条件</summary>':''}<ol>${l.points.map(p=>`<li>${E(p)}</li>`).join('')}</ol>${hasBeginnerNotes(l)?'</details>':''}
 ${diagram?`<h2 id="diagram">图解推演</h2>${hasWalkthrough(l)?renderWalkthrough(l,visualStep[id]||0,spiMode):visual(l)}`:''}
 ${l.code?`<h2 id="example">代码示例</h2><pre class="codeblock"><code>${E(l.code)}</code></pre>`:''}${workedExample(l)}
 ${refs.length?`<h2 id="references">核对原理</h2><div class="lesson-refs">${refs.map(x=>`<a href="${E(x.url)}" target="_blank" rel="noopener noreferrer">${E(x.name)}</a>`).join('')}</div>`:''}
 <button class="btn primary lesson-bottom-practice" data-action="lesson-view" data-id="${id}" data-value="practice">进入本课练习 · ${total} 题 →</button>
 </article><aside class="aside panel"><h3>本课目录</h3><nav class="toc">${l.beginner||hasBeginnerNotes(l)?'<a href="#basics" data-scroll="basics">基础讲解与符号</a>':''}<a href="#why" data-scroll="why">从问题推到结论</a><a href="#concept" data-scroll="concept">关键结论</a>${diagram?'<a href="#diagram" data-scroll="diagram">图解推演</a>':''}${l.code?'<a href="#example" data-scroll="example">代码示例</a>':''}<a href="#worked" data-scroll="worked">推导例题</a></nav><div class="aside-divider"></div><p class="source-note">本课已完成 ${l.quiz.filter(q=>state.answers[q.id]?.submitted).length} / ${l.quiz.length} 道选择题</p><button class="btn soft" data-action="lesson-view" data-id="${id}" data-value="practice">去做随堂练习</button></aside></div>
 <section class="lesson-practice-view" ${view==='practice'?'':'hidden'} aria-label="随堂练习">
 <div class="practice-groups" role="group" aria-label="练习分类">${[['basic','基础巩固',basic.length],['advanced','进阶笔试',advanced.length+written.length],['coding','编程练习',relevant.length]].map(([v,t,n])=>`<button data-action="lesson-group" data-id="${id}" data-value="${v}" aria-pressed="${group===v}">${t}<span>${n}</span></button>`).join('')}</div>
 <div id="quiz" class="exercise-group" ${group==='basic'?'':'hidden'}><div class="exercise-intro"><h2>基础巩固</h2><p>原有简单题全部保留，先检查概念是否理解。</p></div>${basic.map((q,j)=>quizCard(q,j)).join('')}</div>
 <div id="written" class="exercise-group" ${group==='advanced'?'':'hidden'}><div class="exercise-intro"><h2>进阶笔试</h2><p>先独立推导、阅读代码，再展开详细解析。</p></div>${advanced.map((q,j)=>quizCard(q,j)).join('')}${written.map((q,j)=>writtenCard(q,j+advanced.length,state.drafts[q.id])).join('')}${!advanced.length&&!written.length?`<div class="empty">本课暂无进阶笔试题。可先完成基础题，或到本模块练习继续训练。<a class="btn soft" href="#/practice/${l.module}">进入模块练习</a></div>`:''}</div>
 <div id="coding" ${group==='coding'?'':'hidden'}>${selected?`<div class="coding-picker"><label for="lesson-coding-select">本课编程题</label><select id="lesson-coding-select" data-lesson="${id}">${relevant.map((c,j)=>`<option value="${c.id}" ${c.id===selected.id?'selected':''}>${j+1}. ${E(c.title)} · ${E(c.level)}</option>`).join('')}</select><a href="#/challenge/${selected.id}">独立打开 ↗</a></div>${codingWorkbench(selected,state.drafts[selected.id])}`:`<div class="empty">本课暂无编程题。<a class="btn soft" href="#/challenges">浏览全部编程题</a></div>`}</div>
 </section>
 <div class="lesson-nav"><a class="btn ghost" href="${prev?lessonUrl(prev.id):moduleUrl(l.module)}">← ${prev?E(prev.title):'返回目录'}</a><button class="btn ${state.completed[id]?'ghost':'primary'}" data-action="complete" data-id="${id}">${state.completed[id]?'已完成 · 取消标记':'标记学完'}</button><a class="btn ghost" href="${next?lessonUrl(next.id):moduleUrl(l.module)}">${next?E(next.title):'返回目录'} →</a></div>`;
}
function quizCard(q,j,{mockMode=false}={}){const lesson=questionById[q.id].lesson;const rec=mockMode?null:state.answers[q.id];const selected=mockMode?mock?.choices[q.id]:rec?.choice;const revealed=mockMode?mock?.finished:rec?.revealed;const isCorrect=selected===q.answer;return `<section class="quiz-card" id="quiz-${q.id}"><div class="quiz-head"><span class="quiz-num">${j+1}</span><span class="quiz-type">单选题 · ${E(difficulty(q))} · ${E(moduleById[lesson.module].name)} / ${E(lesson.title)}</span></div><div class="quiz-prompt">${E(q.prompt)}</div>${q.code?`<pre class="codeblock"><code>${E(q.code)}</code></pre>`:''}<div class="options">${optionLayouts.get(q.id).map((k,displayIndex)=>`<button class="option ${selected===k?'selected':''} ${revealed&&k===q.answer?'correct':''} ${revealed&&selected===k&&k!==q.answer?'wrong':''}" data-action="${mockMode?'mock-choice':'choose'}" data-id="${q.id}" data-choice="${k}" ${revealed?'disabled':''}><span class="letter">${'ABCD'[displayIndex]}</span><span>${E(q.options[k])}</span></button>`).join('')}</div>${!mockMode?`<div class="quiz-actions"><button class="btn primary small" data-action="submit-answer" data-id="${q.id}" ${selected===undefined||revealed?'disabled':''}>提交答案</button><button class="btn ghost small" data-action="reveal" data-id="${q.id}" ${revealed?'disabled':''}>${revealed?'解析已展开':'不会？查看解析'}</button>${revealed?`<span class="quiz-feedback ${rec?.submitted?(isCorrect?'good':'bad'):''}">${rec?.submitted?(isCorrect?'回答正确':'回答错误，加入错题'):'已查看解析，加入复习'}</span>`:''}</div>`:''}${revealed?`<div class="quiz-answer"><strong>正确答案：${letter(q,q.answer)} · ${E(q.options[q.answer])}</strong>${q.steps?`<p><b>判断依据：</b></p><ol>${q.steps.map(x=>`<li>${E(x)}</li>`).join('')}</ol>`:`<p><b>判断依据：</b>${E(q.explain)}</p>`}${relatedReasoning(lesson)}${selected!==undefined&&selected!==q.answer?`<p><b>你的选择：</b>${letter(q,selected)} · ${E(q.options[selected])}。结合上面的规则，重新检查题干条件和选项所表达的含义。</p>`:''}</div>`:''}</section>`;}
function challengeMini(c){return `<div class="challenge-card"><div class="meta">${E(c.kind)} · ${E(c.level)}</div><h3>${E(c.title)}</h3><p>${E(c.prompt)}</p><a class="btn soft small" href="#/challenge/${c.id}">开始手写 →</a></div>`;}
function practicePage(){
 const inModule=item=>practiceModule==='all'||lessonById[item.lesson]?.module===practiceModule;
 const fits=item=>practiceDifficulty==='all'||difficulty(item)===practiceDifficulty;
 const choices=allQuestions.map(q=>({...q,lesson:questionById[q.id].lesson.id})).filter(inModule).filter(fits).sort((a,b)=>Boolean(b.difficulty)-Boolean(a.difficulty));
 const written=writtenQuestions.filter(inModule).filter(fits),coding=challenges.filter(inModule).filter(fits);
 const lists={choice:choices.map(q=>({type:'choice',item:q})),written:written.map(q=>({type:'written',item:q})),coding:coding.map(q=>({type:'coding',item:q}))};
 let items=[];if(practiceType==='all'){const n=Math.max(...Object.values(lists).map(a=>a.length));for(let i=0;i<n;i++)for(const list of Object.values(lists))if(list[i])items.push(list[i]);}else items=lists[practiceType]||[];
 const visible=items.slice(0,practiceLimit);
 return `${pageHead('PRACTICE','专题练习','基础题复习概念，进阶题练推导、改错与边界；编程题练完整实现。解析默认隐藏。')}<div class="practice-toolbar exam-filters"><label>模块<select id="practice-module"><option value="all">全部模块</option>${modules.map(m=>`<option value="${m.id}" ${practiceModule===m.id?'selected':''}>${E(m.name)}</option>`).join('')}</select></label><label>难度<select id="practice-difficulty">${['all','基础','进阶','挑战'].map(x=>`<option value="${x}" ${practiceDifficulty===x?'selected':''}>${x==='all'?'全部难度':x}</option>`).join('')}</select></label><label>题型<select id="practice-type">${[['all','全部题型'],['choice','选择题'],['written','代码阅读 / 填空 / 改错 / 简答'],['coding','编程 / 场景题']].map(([v,t])=>`<option value="${v}" ${practiceType===v?'selected':''}>${t}</option>`).join('')}</select></label><span>共 ${items.length} 题 · 已展示 ${visible.length}</span></div><div class="practice-grid"><div class="practice-list">${visible.map(({type,item},j)=>type==='choice'?quizCard(item,j):type==='written'?writtenCard(item,j,state.drafts[item.id]):challengeMini(item)).join('')}${practiceLimit<items.length?'<button class="btn ghost" data-action="load-more">加载更多题目 ↓</button>':''}${!items.length?'<div class="empty">此筛选暂无题目，可切换模块、难度或题型。</div>':''}</div><aside class="practice-side panel"><h3>按笔试流程练</h3><p>代码题先逐行计算，改错题说明原因，手写题检查边界与复杂度。不要只核对最后的结果。</p><p>选择题的选项顺序已调整；历史答案与错题记录继续有效。非选择题可保存草稿并按评分点自查。</p><a href="#/challenges" class="btn soft">进入编程题 →</a></aside></div>`;
}
function reviewPage(){const entries=Object.entries(state.answers).filter(([_,a])=>a.needsReview).map(([id,a])=>({q:questionById[id],a})).filter(x=>x.q);const filtered=showOnlyDue?entries.filter(x=>!x.a.due||x.a.due<=Date.now()):entries;return `${pageHead('REVIEW','错题复习','做错或主动查看解析的题会出现在这里。重做正确后安排下一轮复习。')}<div class="filters"><button class="pill ${!showOnlyDue?'active':''}" data-action="review-filter" data-value="all">全部错题 ${entries.length}</button><button class="pill ${showOnlyDue?'active':''}" data-action="review-filter" data-value="due">现在待复习 ${dueCount()}</button></div>${filtered.length?filtered.map(({q,a})=>`<div class="review-card panel"><div class="status-dot" style="background:${a.due&&a.due>Date.now()?'#65b69c':'#e7a25e'}"></div><div class="body"><strong>${E(q.prompt)}</strong><p>${E(q.lesson.title)} · ${a.due&&a.due>Date.now()?'下次复习 '+new Date(a.due).toLocaleDateString('zh-CN'):'现在可复习'}</p></div><a class="btn soft small" href="${lessonUrl(q.lesson.id)}">回到课程</a><button class="btn ghost small" data-action="review-reset" data-id="${q.id}">重做</button></div>`).join(''):`<div class="empty"><div class="big">✓</div>${showOnlyDue?'现在没有待复习的题。':'还没有错题，先去做几道练习。'}<p><a class="btn soft" href="#/practice">进入专题练习</a></p></div>`}`;}
function mockQuestions(){return modules.map(m=>{const pool=allQuestions.filter(q=>questionById[q.id].lesson.module===m.id&&q.difficulty);const fallback=allQuestions.filter(q=>questionById[q.id].lesson.module===m.id);const pick=pool.length?pool:fallback;return pick[Math.floor(Math.random()*pick.length)];}).filter(Boolean);}
function mockPage(){if(!mock)return `${pageHead('TIMED PRACTICE','模拟笔试','优先抽取进阶题，12 道跨模块选择题，限时 20 分钟；提交后显示分数与逐题解析。')}<div class="mock-intro"><div class="mock-stat"><div><strong>12</strong><br>道题</div><div><strong>20</strong><br>分钟</div><div><strong>12</strong><br>覆盖模块</div></div><p>模拟过程中隐藏答案。你可以跳过不会的题，提交后统一查看解析。</p><button class="btn primary" data-action="mock-start">开始模拟 →</button></div>`;const elapsed=Math.floor((Date.now()-mock.started)/1000),left=Math.max(0,1200-elapsed),min=String(Math.floor(left/60)).padStart(2,'0'),sec=String(left%60).padStart(2,'0');const score=mock.questions.filter(q=>mock.choices[q.id]===q.answer).length;return `${pageHead('TIMED PRACTICE','模拟笔试',mock.finished?'已提交，可以查看逐题解析。':'作答时答案隐藏，结束后统一批改。',`<span class="mock-timer">${mock.finished?'已结束':min+':'+sec}</span>`)}${mock.finished?`<div class="result"><strong>${score} / ${mock.questions.length} 题正确</strong><p>错题可回到对应课程继续练习。本次模拟不覆盖课程中的历史答案。</p></div>`:`<div class="mock-banner"><span>已作答 ${Object.keys(mock.choices).length} / ${mock.questions.length}</span><button class="btn primary small" data-action="mock-finish">交卷并查看解析</button></div>`}${mock.questions.map((q,j)=>quizCard(q,j,{mockMode:true})).join('')}${!mock.finished?`<button class="btn primary" data-action="mock-finish">交卷并查看解析</button>`:'<button class="btn ghost" data-action="mock-reset">再做一次</button>'}`;}
function challengesPage(){const items=challenges.filter(c=>(codingModule==='all'||lessonById[c.lesson].module===codingModule)&&(codingDifficulty==='all'||difficulty(c)===codingDifficulty));return `${pageHead('CODING LAB','手写与场景题','新增算法与嵌入式手写题，练习边界、复杂度和错误路径。参考解默认隐藏；可去原题平台提交。')}<div class="practice-toolbar exam-filters"><label>模块<select id="coding-module"><option value="all">全部模块</option>${modules.map(m=>`<option value="${m.id}" ${codingModule===m.id?'selected':''}>${E(m.name)}</option>`).join('')}</select></label><label>难度<select id="coding-difficulty">${['all','基础','进阶','挑战'].map(x=>`<option value="${x}" ${codingDifficulty===x?'selected':''}>${x==='all'?'全部难度':x}</option>`).join('')}</select></label><span>共 ${items.length} 题</span></div><div class="course-list">${items.map((c,j)=>`<a href="#/challenge/${c.id}" class="course-card"><span class="course-num">${String(j+1).padStart(2,'0')}</span><div class="course-body"><strong>${E(c.title)}</strong><p>${E(moduleById[lessonById[c.lesson].module].name)} · ${E(c.kind)} · ${E(c.prompt)}</p></div><div class="course-side"><span class="badge p1">${E(difficulty(c))}</span><span class="arrow">›</span></div></a>`).join('')}</div>${!items.length?'<div class="empty">此筛选暂无题目，请切换模块或难度。</div>':''}<p class="source-note">站内题干、样例与参考解独立编写，链接用于同类原题练习；原平台题意与约束以原页面为准。站内保存草稿，代码运行与判题在原平台或本地进行。</p>`;}
function challengePage(id){
 const c=challenges.find(x=>x.id===id);if(!c)return notFound();const l=lessonById[c.lesson];
 return `<div class="crumb"><a href="#/challenges">编程题库</a> / <a href="${lessonUrl(l.id)}/coding">${E(l.title)}</a></div><header class="challenge-heading"><div><div class="eyebrow">${E(c.language||c.kind)} · ${E(c.level)}</div><h1>${E(c.title)}</h1></div><a class="btn ghost" href="${lessonUrl(l.id)}/coding">返回随堂练习</a></header>${codingWorkbench(c,state.drafts[c.id])}`;
}
function sourcesPage(){return `${pageHead('REFERENCES','资料来源','核心技术内容参考语言规范、芯片手册和 FreeRTOS 官方文档。')}<div class="source-list">${sources.map(s=>`<a class="source-item panel" href="${E(s.url)}" target="_blank" rel="noopener noreferrer"><strong>${E(s.name)} ↗</strong><p>${E(s.note)}</p></a>`).join('')}</div><div class="section-head"><h2>我的学习记录</h2></div><div class="settings panel"><p>进度、错题和代码草稿保存在这个浏览器里。建议定期导出备份；导入会覆盖当前浏览器中的学习记录。</p><div class="settings-row"><button class="btn primary small" data-action="export">导出学习记录</button><button class="btn ghost small" data-action="import">导入学习记录</button><input id="import-file" type="file" accept="application/json,.json" hidden></div></div><div class="section-head"><h2>内容说明</h2></div><p class="source-note">当前网站提供 ${lessons.length} 课、${questionCount} 道选择题、${writtenQuestions.length} 道非选择笔试题和 ${challenges.length} 道手写或场景练习。芯片相关结论以 F407/L476 对应设备手册为准；课程中的图是帮助理解的简化模型。</p>`;}
function searchPage(){const q=searchTerm.trim().toLowerCase();const matches=q?lessons.filter(l=>`${l.title} ${l.summary} ${l.points.join(' ')} ${(tutorialFor(l)?.steps||[]).join(' ')} ${tutorialFor(l)?.worked.prompt||''} ${moduleById[l.module].name}`.toLowerCase().includes(q)):[];const qmatches=q?lessons.flatMap(l=>l.quiz.map(x=>({...x,lesson:l}))).filter(x=>x.prompt.toLowerCase().includes(q)):[];return `${pageHead('SEARCH','搜索结果',q?`“${q}” 找到 ${matches.length} 个知识点、${qmatches.length} 道相关练习。`:'输入关键词搜索知识点和题目。')}${matches.length?`<div class="section-head"><h2>知识点</h2></div><div class="course-list">${matches.map(courseCard).join('')}</div>`:''}${qmatches.length?`<div class="section-head"><h2>练习题</h2></div>${qmatches.slice(0,15).map(({lesson,...x})=>`<a class="review-card panel" href="${lessonUrl(lesson.id)}"><div class="body"><strong>${E(x.prompt)}</strong><p>${E(lesson.title)}</p></div><span style="color:#abb7c9">›</span></a>`).join('')}`:''}${q&&!matches.length&&!qmatches.length?'<div class="empty">没有找到相关内容。试试“指针”“SPI”“队列”等关键词。</div>':''}`;}

// All diagrams are original SVG/HTML teaching illustrations. Their labels are part of the lesson data.
function visual(l){const step=visualStep[l.id]||0;let body='',caption='点击“下一步”查看推演。',controls='';
  const rect=(x,y,w,h,fill='#fff',stroke='#cdd9eb',rx=7)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}" stroke="${stroke}"/>`;
  const txt=(x,y,t,size=13,color='#49617e',anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${color}" font-size="${size}">${E(t)}</text>`;
  const line=(x1,y1,x2,y2,color='#8ba3c6',dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="2" ${dash?'stroke-dasharray="4 4"':''} marker-end="url(#arrow)"/>`;
  const defs=`<defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 7 3.5 0 7" fill="none" stroke="#8ba3c6" stroke-width="1.4"/></marker></defs>`;
  switch(l.visual){
    case 'pointer':{const phase=step%4;body+=txt(40,35,'指针对象 p',12,'#5a718f','start')+txt(310,35,'整数对象 x',12,'#5a718f','start');body+=rect(42,58,150,84,'#e6f0ff')+txt(117,93,phase===3?'悬空地址':'0x1000',16,'#275ab5')+txt(117,118,'p 的值 = 地址',11,'#738dad');body+=rect(308,58,150,84,phase===3?'#fff0ef':phase===2?'#def4e9':'#fff')+txt(383,94,phase===2?'7':'42',23,phase===3?'#cb7373':'#2c629b')+txt(383,119,'x 位于 0x1000',11,'#738dad');body+=line(193,99,304,99,phase===3?'#d58a8a':'#5592dc',phase===3);body+=txt(250,179,['&x：取得对象 x 的地址','*p：沿地址访问对象 x','*p = 7：修改 x 的值','x 生命周期结束：p 不能再解引用'][phase],12,'#537092');caption=['p 自身也占存储空间，里面保存 0x1000；右侧 x 才是数据对象。','解引用 p 访问的是它指向的 x，不是指针对象 p。','通过 *p 写入 7 后，x 的值随之改变。','地址数值可能仍留在 p 中，但对象已失效，继续 *p 不安全。'][phase];break;}
    case 'string':{const chars=['h','e','l','l','o','\\0'];for(let i=0;i<6;i++){const x=43+i*72;body+=rect(x,68,64,62,i===step%6?'#dcecff':i===5?'#fff0dd':'#fff')+txt(x+32,107,chars[i],i===5?13:18,'#2f629b')+txt(x+32,152,String(i),10,'#9aa9bd');}body+=txt(250,198,'sizeof(s)=6 个 char　·　strlen(s)=5',13,'#526b8b');caption=`索引 ${step%6}：${step%6===5?'末尾是零字符，strlen 在这里停止。':'这是有效字符之一，strlen 继续向后扫描。'}`;break;}
    case 'lifecycle':{const events=['基类构造','成员构造','派生类构造','派生类析构','成员析构','基类析构'];events.forEach((event,i)=>{const x=23+(i%3)*155,y=44+Math.floor(i/3)*88;body+=rect(x,y,145,59,i===step%6?'#dceaff':'#fff')+txt(x+72,y+35,event,12,i===step%6?'#255cbd':'#6b7e9c');});caption=`第 ${step%6+1} 步：${events[step%6]}。构造先基类与成员，再派生类；析构基本反向。`;break;}
    case 'ownership':{const phase=step%3;body+=rect(35,68,105,64,'#e5efff')+txt(87,105,'对象 A',13,'#2e61a8')+rect(190,68,105,64,'#e5efff')+txt(242,105,'对象 B',13,'#2e61a8')+rect(370,68,100,64,phase===1?'#ffe7e6':'#dff4ec')+txt(420,105,'堆资源',13,phase===1?'#bd5c62':'#29866e');body+=line(141,99,365,99);if(phase!==2)body+=line(296,115,365,115);caption=['浅拷贝后，A、B 的裸指针可能都指向同一资源。','若 A、B 析构都释放该地址，会发生重复释放。','独占所有权示意：仅 A 拥有并释放资源，B 不再持有资源。'][phase];break;}
    case 'endian':{const little=step%2===0;const bytes=little?['0x34','0x12']:['0x12','0x34'];body+=txt(250,48,`整数值 0x1234 · ${little?'小端内存':'大端报文'}`,15,'#42648d');bytes.forEach((b,i)=>{const x=128+i*132;body+=rect(x,78,116,69,'#e3efff')+txt(x+58,119,b,19,'#2d5ea9')+txt(x+58,168,i===0?'低地址':'高地址',11,'#8ca0bb');});caption=little?'小端内存：低有效字节 0x34 放在低地址。':'大端报文：高有效字节 0x12 先出现；解析应按协议移位组装。';break;}
    case 'graph':{const positions=[[60,108,'A'],[190,52,'B'],[190,166,'C'],[350,52,'D'],[350,166,'E']];body+=`<path d="M78 102 169 60 M78 116 169 158 M211 52 329 52 M211 166 329 166 M211 67 329 150" fill="none" stroke="#a7bad8" stroke-width="2"/>`;positions.forEach(([x,y,n],i)=>{body+=`<circle cx="${x}" cy="${y}" r="21" fill="${i<=step%5?'#4d80d9':'#e7f0ff'}"/>`+txt(x,y+5,n,13,i<=step%5?'#fff':'#4873ad')});caption=`BFS 示意：队列让先发现的节点先扩展。已标记 ${step%5+1} 个节点，visited 防止重复访问。`;break;}
    case 'deadlock':{body+=rect(45,55,122,62,'#e4edff')+txt(106,92,'任务 A 持有 X',12)+rect(332,55,122,62,'#fff0dc')+txt(393,92,'任务 B 持有 Y',12)+rect(45,156,122,46,'#fff0dc')+txt(106,184,'等待 Y',12)+rect(332,156,122,46,'#e4edff')+txt(393,184,'等待 X',12)+line(106,119,106,152)+line(393,119,393,152)+line(169,178,328,178);caption=step%2?'统一按 X→Y 的顺序申请锁，可以打破循环等待。':'A 持有 X 等 Y，B 持有 Y 等 X，形成等待环。';break;}
    case 'notify':{const labels=['UART ISR','FromISR 通知','任务就绪','任务处理'];labels.forEach((v,i)=>{const x=17+i*122;body+=rect(x,83,109,58,i===step%4?'#dceaff':'#fff')+txt(x+54,117,v,11,'#4d6f9b');if(i<3)body+=line(x+110,112,x+119,112)});caption=['中断中先确认硬件事件。','使用 FromISR API 发通知，并满足 NVIC 优先级限制。','等待通知的任务从阻塞变就绪。','任务中完成耗时解析，ISR 保持短小。'][step%4];break;}
    case 'timer':{for(let i=0;i<6;i++){const x=44+i*73;body+=rect(x,72,60,56,i===step%6?'#dceaff':'#fff')+txt(x+30,105,i%2?'回调':'Tick',11,'#56749a');}caption='软件定时器由服务任务运行回调；回调阻塞会延迟后续定时器处理。';break;}
    case 'callback':{body+=rect(28,74,122,69,'#e4efff')+txt(89,104,'回调表',13)+txt(89,126,'fp[opcode]',11)+rect(202,74,122,69,'#e4efff')+txt(263,109,'函数指针',13)+rect(376,74,100,69,'#dff3e9')+txt(426,109,'处理函数',13)+line(152,108,198,108)+line(326,108,372,108);caption='先检查命令索引与函数指针非空，再通过相同函数签名调用对应处理函数。';break;}
    case 'adc':{body+=`<path d="M54 173 153 139 251 110 350 77 449 45" fill="none" stroke="#4990d9" stroke-width="3"/>`;for(let i=0;i<8;i++){const x=55+i*55,y=174-Math.floor(i*7/8)*18;body+=`<circle cx="${x}" cy="${y}" r="4" fill="#ec9f54"/>`;}body+=txt(250,210,'模拟电压 → 分档码值；分压比决定电池实际电压',12,'#647f9e');caption='ADC 将连续输入量化。12 位共有 4096 个可能码，电压换算还需参考电压与分压比。';break;}
    case 'memory':{const values=step%2?['7','2','3','4','5']:['1','2','3','4','5'];body+=txt(37,35,'地址',11,'#8b9db7','start');for(let i=0;i<5;i++){const x=68+i*70;body+=rect(x,58,61,54,i===0?'#e2edff':'#fff')+txt(x+30,91,values[i],18,'#244a89')+txt(x+30,130,`0x${(1000+i*4).toString(16).toUpperCase()}`,10,'#8da0ba');}body+=rect(140,158,110,38,'#eaf8f1','#9ad5bf')+txt(195,182,'p = &a[0]',13,'#208269')+line(195,158,97,112);caption=step%2?'*p = 7：通过指针改写它指向的对象。':'数组元素连续存放；int* 加 1 前进一个 int。';break;}
    case 'array-pointer':{body+=txt(28,30,'二维数组 m[2][4]',12,'#556b89','start');for(let row=0;row<2;row++)for(let col=0;col<4;col++){const x=75+col*78,y=48+row*72;body+=rect(x,y,69,48,step%2===row?'#e4efff':'#fff')+txt(x+34,y+30,String(row*4+col+1),15,'#285491');}body+=txt(52,80,'第 0 行',10,'#8395ae','end')+txt(52,152,'第 1 行',10,'#8395ae','end')+line(405,step%2?148:76,391,step%2?148:76)+txt(412,step%2?150:78,step%2?'p + 1':'p',12,'#275dc2','start');caption=step%2?'p+1 指向下一整行，步长为 4×sizeof(int)。':'p 的类型是 int (*)[4]，它指向完整的一行。';break;}
    case 'struct':{const cells=[['c','1 B'],['填充','3 B'],['value','4 B']];let x=53;for(let i=0;i<3;i++){const w=[62,138,180][i];body+=rect(x,67,w,75,i===1?'#fff0dc':'#e5efff')+txt(x+w/2,97,cells[i][0],13,i===1?'#b87530':'#275896')+txt(x+w/2,121,cells[i][1],11,'#8da1ba');x+=w+4;}body+=txt(50,52,'0',10,'#91a2b9')+txt(122,52,'1',10,'#91a2b9')+txt(269,52,'4',10,'#91a2b9')+txt(465,52,'8',10,'#91a2b9');caption='示意：常见 4 字节 int 对齐环境中，char 后有 3 字节填充；具体仍以 ABI 为准。';break;}
    case 'sort':{const arrays=[[5,1,4,2,3],[1,5,4,2,3],[1,4,5,2,3],[1,4,2,5,3],[1,4,2,3,5],[1,2,4,3,5],[1,2,3,4,5]];const a=arrays[Math.min(step,6)];a.forEach((v,i)=>{const x=90+i*70,h=v*24;body+=rect(x,177-h,42,h,step===6?'#72bea8':i===Math.min(step,4)?'#5082dc':'#a7c2ef','none',4)+txt(x+21,196,String(v),12,'#5c718f');});caption=step===6?'完成排序：这组数从小到大。':`冒泡排序示意，第 ${step+1} 个状态：比较相邻元素并交换逆序对。`;break;}
    case 'tree':{const coords=[[250,48,'A'],[152,125,'B'],[348,125,'C'],[95,197,'D'],[207,197,'E']];body+=`<path d="M250 60 152 111 M250 60 348 111 M152 137 95 183 M152 137 207 183" fill="none" stroke="#a8bddf" stroke-width="2"/>`;coords.forEach(([x,y,label],i)=>{body+=`<circle cx="${x}" cy="${y}" r="23" fill="${i===[0,1,3,4,2][step%5]?'#3e74d5':'#e9f1ff'}" stroke="#9eb9e9"/>`+txt(x,y+5,label,14,i===[0,1,3,4,2][step%5]?'#fff':'#3667b8');});caption=`先序遍历：A → B → D → E → C。当前高亮第 ${step%5+1} 个访问节点。`;break;}
    case 'list':{for(let i=0;i<4;i++){const x=47+i*111;body+=rect(x,78,79,57,i<=step%4?'#def2eb':'#e8f0ff')+txt(x+39,112,String(i+1),17,'#28558a');if(i<3)body+=line(x+80,106,x+105,106)}body+=txt(248,178,step%4===0?'开始：prev = NULL，cur 指向头节点。':`已处理 ${step%4+1} 个节点：每轮先保存 next，再反转连接。`,12,'#64809e');caption='逐节点反转时，先保存原后继，防止断链。';break;}
    case 'queue':{for(let i=0;i<6;i++){const x=41+i*76;body+=rect(x,74,66,56,i===step%6?'#dff3e9':'#eaf1ff')+txt(x+33,106,i<4?String(i+1):'·',16,'#316194')+txt(x+33,151,String(i),10,'#9aacc2');}body+=txt(52,41,'head → 出队',11,'#259376','start')+txt(450,41,'tail → 入队',11,'#2b65c6','end');caption=`固定容量数组首尾相接；当前高亮槽位 ${step%6}。空满需要明确规则。`;break;}
    case 'spi':{controls=`<select id="spi-mode" aria-label="选择 SPI 模式">${[0,1,2,3].map(n=>`<option value="${n}" ${spiMode===n?'selected':''}>模式 ${n}</option>`).join('')}</select>`;const pol=Math.floor(spiMode/2),pha=spiMode%2;body+=txt(30,50,'CS',11,'#7890ab','start')+txt(30,105,'SCK',11,'#7890ab','start')+txt(30,158,'MOSI',11,'#7890ab','start');body+=`<path d="M80 30 H120 V48 H445 V30 H475" stroke="#e09859" stroke-width="3" fill="none"/>`;let d=`M80 ${pol?85:117} H120`;for(let k=0;k<8;k++){const x=120+k*38;d+=` V${(k%2===0)!==Boolean(pol)?85:117} H${x+38}`}body+=`<path d="${d}" fill="none" stroke="#3973d1" stroke-width="3"/>`;body+=`<path d="M80 166 H120 V148 H196 V166 H272 V148 H348 V166 H445" fill="none" stroke="#43a58b" stroke-width="3"/>`;const sx=120+(pha?38:0);body+=`<line x1="${sx}" x2="${sx}" y1="65" y2="176" stroke="#e89953" stroke-width="2" stroke-dasharray="5 5"/>`+txt(370,205,`CPOL=${pol}  CPHA=${pha}`,13,'#49617e');caption=`模式 ${spiMode}：空闲${pol?'高':'低'}，第${pha?'二':'一'}个边沿采样（${pol!==pha?'下降':'上升'}沿）。橙色虚线示意采样时刻。`;break;}
    case 'uart':{const labels=['起始','D0','D1','D2','D3','D4','D5','D6','D7','停止'];labels.forEach((lab,i)=>{const x=29+i*46;body+=rect(x,66,43,50,i===0?'#ffecd6':i===9?'#def4e8':'#e5eeff')+txt(x+21,95,lab,11,'#416185');});body+=txt(250,151,'8N1 = 1 起始 + 8 数据 + 1 停止 = 10 位时间',12,'#5b7292');caption='UART 仅规定字节传输；应用报文的帧头、长度和校验需另行设计。';break;}
    case 'schedule':{const lanes=[['高优先级','#4d7cda',[0,1,1,0,1,1]],['中优先级','#e4aa6b',[1,0,0,1,0,0]],['低优先级','#6cba9f',[0,0,0,0,0,0]]];lanes.forEach(([name,color,slots],r)=>{body+=txt(85,56+r*52,name,11,'#5d7190');slots.forEach((on,i)=>body+=rect(135+i*56,36+r*52,52,26,on?color:'#edf1f6','none',4));});body+=txt(150,205,'时间 →',11,'#9ba9bd','start');caption='简化单核调度时间线。高优先级就绪时先运行；锁等待可使任务阻塞。';break;}
    case 'sections':{const blocks=[['Flash','.text / .rodata','#dfeaff'],['Flash 初值','.data 初值','#dfeaff'],['SRAM','.data / .bss','#dff4eb'],['SRAM','堆 ↕ 栈','#e8f3ed']];blocks.forEach(([where,what,color],i)=>{const x=25+i*119;body+=rect(x,72,110,85,color)+txt(x+55,107,where,12,'#477294')+txt(x+55,131,what,10,'#6f829e');});caption='复位时启动代码把 .data 初值从 Flash 复制到 SRAM，并清零 .bss。';break;}
    case 'dma':{body+=rect(35,70,112,70,step%2?'#e3f4eb':'#e2edff')+rect(197,70,112,70,step%2?'#e2edff':'#e3f4eb')+rect(358,70,109,70,'#fff0df')+txt(91,100,'Buffer A',13)+txt(91,124,step%2?'UI 绘制':'DMA 读取',11)+txt(253,100,'Buffer B',13)+txt(253,124,step%2?'DMA 读取':'UI 绘制',11)+txt(412,100,'SPI 屏幕',13)+line(step%2?309:147,104,357,104);caption=step%2?'DMA 发送 B；UI 可绘制 A。完成后才能再次使用 B。':'DMA 发送 A；UI 可绘制 B。缓冲区所有权不能交叉。';break;}
    case 'lowpower':{const names=['运行','息屏准备','STOP1','唤醒恢复'];names.forEach((n,i)=>{const x=20+i*120;body+=rect(x,72,105,66,i===step%4?'#dbeafe':'#fff')+txt(x+52,109,n,12,i===step%4?'#2c60bb':'#7183a0');if(i<3)body+=line(x+107,105,x+117,105)});caption=['处理任务与外设事件。','等待 DMA/Flash，配置唤醒源，记录测量条件。','进入 STOP1，按芯片手册评估保留内容与电流。','恢复时钟、外设、屏幕和任务时间基准。'][step%4];break;}
    case 'clock':{const names=['HSI/HSE','PLL','AHB/APB','TIM / UART'];names.forEach((n,i)=>{const x=20+i*120;body+=rect(x,72,105,66,i===step%4?'#dfebff':'#fff')+txt(x+52,109,n,12,i===step%4?'#2c60bb':'#7183a0');if(i<3)body+=line(x+107,105,x+117,105)});caption='时钟沿着源、倍频、总线分频到达外设；计算 PWM/UART 前先确认外设实际时钟。';break;}
    case 'pwm':{body+=txt(35,46,'CNT',11,'#8496ad','start')+`<path d="M45 162 120 70 194 162 269 70 344 162 419 70" fill="none" stroke="#3e74d0" stroke-width="3"/>`+`<line x1="45" y1="115" x2="440" y2="115" stroke="#e4a15c" stroke-width="2" stroke-dasharray="5 4"/>`+txt(450,119,'CCR',11,'#bc7d37','start')+txt(222,201,'PSC 决定计数速度 · ARR 决定周期 · CCR 决定比较点',12,'#6e829e');caption='简化计数器与比较值图。具体输出极性和 PWM 模式还要看配置。';break;}
    case 'i2c':{body+=txt(24,65,'SCL',12,'#68809c','start')+txt(24,145,'SDA',12,'#68809c','start');body+=`<path d="M70 42 H120 V82 H170 V42 H220 V82 H270 V42 H320 V82 H370 V42 H450" fill="none" stroke="#4077d3" stroke-width="3"/>`+`<path d="M70 116 H100 V158 H145 V116 H245 V158 H420 V116 H475" fill="none" stroke="#36a186" stroke-width="3"/>`;body+=`<line x1="100" x2="100" y1="31" y2="177" stroke="#e99d51" stroke-width="2" stroke-dasharray="4 4"/>`+txt(103,205,'START',11,'#bd7e3a')+txt(268,205,'数据 / ACK',11,'#67809d')+txt(441,205,'STOP',11,'#bd7e3a');caption=step%2?'SCL 高时 SDA 上升是 STOP；数据位变化通常应避开 SCL 高电平。':'SCL 高时 SDA 下降是 START；第 9 个时钟由接收方给出 ACK/NACK。';break;}
    case 'can':{const a=['1','0','1','1','0'],b=['1','0','0','1','0'];body+=txt(30,50,'A',12,'#5276ab','start')+txt(30,110,'B',12,'#5276ab','start')+txt(30,170,'总线',12,'#5276ab','start');for(let i=0;i<5;i++){const x=92+i*72,win=i===2;body+=rect(x,32,59,35,win?'#fff2df':'#e4efff')+txt(x+29,55,a[i],14)+rect(x,92,59,35,win?'#fff2df':'#e4efff')+txt(x+29,115,b[i],14)+rect(x,152,59,35,win?'#e2f3e9':'#e4efff')+txt(x+29,175,a[i]==='0'||b[i]==='0'?'0':'1',14);}caption='第 3 个仲裁位：A 发隐性 1，B 发显性 0，总线读到 0，因此 A 退出仲裁；实际还须满足完整仲裁字段条件。';break;}
    case 'stack':{const names=['R0–R3','R12','LR','PC','xPSR'];names.forEach((n,i)=>{const x=25+i*95;body+=rect(x,70,88,64,i===step%5?'#dceaff':'#fff')+txt(x+44,105,n,13,'#4b6d99');});body+=txt(251,190,'异常硬件基本现场 · 从正确的 MSP/PSP 栈帧读取',12,'#7388a2');caption=`当前高亮 ${names[step%5]}：结合故障状态寄存器、map 文件与反汇编分析异常。`;break;}
  }
  return `<div class="visual"><div class="visual-top"><strong>交互图解 · ${E(l.title)}</strong><div class="visual-controls">${controls}<button class="btn ghost small" data-action="visual-next" data-id="${l.id}">下一步 →</button></div></div><svg viewBox="0 0 500 230" role="img" aria-label="${E(l.title)} 图解">${defs}${body}</svg><div class="visual-caption">${E(caption)}</div></div>`;}

document.addEventListener('click',event=>{
  const target=event.target.closest('[data-action], [data-scroll]');if(!target)return;
  if(target.dataset.scroll){event.preventDefault();document.getElementById(target.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
  const action=target.dataset.action,id=target.dataset.id;
  if(action==='lesson-view'){lessonView[id]=target.dataset.value;renderMain();return;}
  if(action==='lesson-group'){lessonLevel[id]=target.dataset.value;renderMain(true);return;}
  if(action==='copy-code'||action==='download-code'){const el=document.querySelector('[data-draft="'+id+'"]');if(!el)return;const code=el.value;if(action==='copy-code'){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(code).then(()=>toast('代码已复制')).catch(()=>toast('复制失败，请在编辑区选择代码后复制。'));else toast('请在编辑区选择代码后复制。');}else{const c=challenges.find(x=>x.id===id),blob=new Blob([code],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=id+(c?.language==='C11'?'.c':'.cpp');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}return;}
  if(action==='toggle-menu'){mobileOpen=!mobileOpen;shell();return;}
  if(action==='close-menu'){mobileOpen=false;shell();return;}
  if(['walk-prev','walk-next','walk-reset'].includes(action)){const l=lessonById[id],w=l&&walkthroughFor(l,spiMode);if(!w)return;const current=visualStep[id]||0;visualStep[id]=action==='walk-reset'?0:Math.max(0,Math.min(w.frames.length-1,current+(action==='walk-next'?1:-1)));renderMain(true);document.querySelector(`[data-action="${action}"][data-id="${id}"]`)?.focus();return;}
  if(action==='visual-next'){visualStep[id]=(visualStep[id]||0)+1;renderMain(true);return;}
  if(action==='choose'){const old=state.answers[id]||{};state.answers[id]={...old,choice:Number(target.dataset.choice)};saveState();renderMain(true);return;}
  if(action==='submit-answer'||action==='reveal'){
    const q=questionById[id],old=state.answers[id]||{};if(!q)return;
    if(action==='submit-answer'&&old.choice===undefined)return;
    recordAnswer(id,action==='reveal');renderMain(true);return;
  }
  if(action==='complete'){state.completed[id]=!state.completed[id];saveState();renderMain(true);toast(state.completed[id]?'已标记完成':'已取消完成标记');return;}
  if(action==='load-more'){practiceLimit+=12;renderMain(true);return;}
  if(action==='review-filter'){showOnlyDue=target.dataset.value==='due';renderMain(true);return;}
  if(action==='review-reset'){const l=questionById[id].lesson;lessonView[l.id]='practice';lessonLevel[l.id]=questionById[id].difficulty?'advanced':'basic';const old=state.answers[id]||{};state.answers[id]={...old,choice:undefined,revealed:false,submitted:false};saveState();location.hash=lessonUrl(questionById[id].lesson.id);return;}
  if(action==='hint'||action==='solution'){const el=document.getElementById(action==='hint'?'challenge-hint':'challenge-solution');if(el){el.hidden=!el.hidden;target.setAttribute('aria-expanded',String(!el.hidden));}return;}
  if(action==='mock-start'){mock={started:Date.now(),finished:false,choices:{},questions:mockQuestions()};startMockTimer();renderMain();return;}
  if(action==='mock-choice'){if(mock&&!mock.finished){mock.choices[id]=Number(target.dataset.choice);renderMain(true);}return;}
  if(action==='mock-finish'){if(mock){mock.finished=true;clearInterval(mockTimer);renderMain();window.scrollTo(0,0);}return;}
  if(action==='mock-reset'){mock=null;clearInterval(mockTimer);renderMain();return;}
  if(action==='export'){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='嵌入式学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}
  if(action==='import'){document.getElementById('import-file')?.click();return;}
});
document.addEventListener('input',event=>{if(event.target.matches('[data-draft]')){state.drafts[event.target.dataset.draft]=event.target.value;const ok=saveState();const status=document.querySelector('[data-draft-status="'+event.target.dataset.draft+'"]');if(status)status.textContent=ok?'已保存到本机':'保存失败，请复制备份';}if(event.target.id==='site-search'){searchTerm=event.target.value;if(route!=='search'){route='search';routeArg='';history.replaceState(null,'','#/search');}renderMain();}});
document.addEventListener('change',async event=>{
  if(event.target.id==='lesson-coding-select'){lessonCodeChoice[event.target.dataset.lesson]=event.target.value;renderMain(true);}
  if(event.target.id==='practice-module'){practiceModule=event.target.value;practiceLimit=12;renderMain();}
  if(event.target.id==='practice-difficulty'){practiceDifficulty=event.target.value;practiceLimit=12;renderMain();}
  if(event.target.id==='practice-type'){practiceType=event.target.value;practiceLimit=12;renderMain();}
  if(event.target.id==='coding-module'){codingModule=event.target.value;renderMain();}
  if(event.target.id==='coding-difficulty'){codingDifficulty=event.target.value;renderMain();}
  if(event.target.id==='spi-mode'){spiMode=Number(event.target.value);visualStep['p-spi']=0;renderMain(true);}
  if(event.target.id==='import-file'){const file=event.target.files?.[0];if(!file)return;try{const payload=JSON.parse(await file.text());if(payload.version!==1||!payload.data||typeof payload.data.completed!=='object'||typeof payload.data.answers!=='object'||typeof payload.data.drafts!=='object')throw new Error('format');if(!confirm('导入会覆盖当前浏览器的学习记录。确定继续吗？'))return;state={completed:payload.data.completed,answers:payload.data.answers,drafts:payload.data.drafts,lastLesson:payload.data.lastLesson||null};saveState();render();toast('学习记录已导入。');}catch{toast('导入失败：文件格式不正确。');}}
});
document.addEventListener('keydown',event=>{if(event.target.id==='site-search'&&event.key==='Enter'){location.hash='#/search';event.target.blur();}});
function startMockTimer(){clearInterval(mockTimer);mockTimer=setInterval(()=>{if(!mock||mock.finished){clearInterval(mockTimer);return;}if(Date.now()-mock.started>=1200000){mock.finished=true;clearInterval(mockTimer);renderMain();toast('20 分钟已到，试卷已自动提交。');return;}const el=document.querySelector('.mock-timer');if(el){const s=1200-Math.floor((Date.now()-mock.started)/1000);el.textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}},1000);}
function recordAnswer(id,revealOnly=false){const q=questionById[id];if(!q)throw new Error('题目不存在');const old=state.answers[id]||{};if(!revealOnly&&old.choice===undefined)throw new Error('请先选择答案');const wrong=revealOnly||old.choice!==q.answer;const streak=wrong?0:(old.streak||0)+1;const days=wrong?0:[1,3,7,14][Math.min(streak-1,3)];const needsReview=wrong||Boolean(old.needsReview)&&streak<4;state.answers[id]={...old,revealed:true,submitted:!revealOnly,wrong,needsReview,due:Date.now()+days*86400000,streak};saveState();return {correct:!wrong,answer:q.answer,answerText:q.options[q.answer],explain:q.explain,needsReview};}
function registerWebMcp(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const register=tool=>{try{Promise.resolve(ctx.registerTool(tool)).catch(()=>{});}catch{}};
  register({name:'list_study_lessons',title:'查看课程目录',description:'列出嵌入式学习站的课程和完成状态。',inputSchema:{type:'object',properties:{module:{type:'string',description:'可选模块 ID'}},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){const mod=input?.module;if(mod!==undefined&&!moduleById[mod])throw new Error('模块不存在');return lessons.filter(l=>!mod||l.module===mod).map(l=>({id:l.id,title:l.title,module:l.module,level:l.level,completed:!!state.completed[l.id]}));}});
  register({name:'open_study_lesson',title:'打开课程',description:'在当前页面打开指定课程。',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const id=input?.lessonId;if(!lessonById[id])throw new Error('课程不存在');location.hash=lessonUrl(id);return {opened:id,title:lessonById[id].title};}});
  register({name:'submit_study_answer',title:'提交练习答案',description:'提交某道选择题的选项，更新学习记录并返回答案解析。',inputSchema:{type:'object',properties:{questionId:{type:'string'},choice:{type:'integer',minimum:0,maximum:3}},required:['questionId','choice'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const id=input?.questionId,q=questionById[id],choice=input?.choice;if(!q||!Number.isInteger(choice)||choice<0||choice>=q.options.length)throw new Error('题目或选项无效');state.answers[id]={...(state.answers[id]||{}),choice};const result=recordAnswer(id);if(route==='lesson'||route==='practice'||route==='review')renderMain(true);return {questionId:id,...result};}});
}
window.addEventListener('hashchange',setRoute);
setRoute();
registerWebMcp();
